import 'dart:io';

class StreamSink<T> {
  List<StreamConsumer<T>> _consumers = [];


  void add(StreamConsumer<T> consumer) {
    if (!_consumers.contains(consumer)) {
      _consumers.add(consumer);
    }
  }


  void remove(StreamConsumer<T> consumer) {
    _consumers.remove(consumer);
  }


  void emit(T data) {

    for (final consumer in _consumers) {
      try {
        consumer(data);
      } catch (e, stackTrace) {

        print('Error while emitting to a stream consumer:');
        print(e.toString());
        print(stackTrace.toString());
      }
    }
  }
}


typedef StreamConsumer<T> = void Function(T);

void main() {


  final sink = StreamSink<int>();


  sink.add((int value) {
    print('Received from Sink A: $value');
  });

  sink.add((int value) {
    print('Received from Sink B: $value');
  });


  int receivedValue;
  stdin.listen((data) {
    final input = int.tryParse(data.trim());
    if (input != null) {
      sink.emit(input);

      stdout.write('Enter another number (-1 to exit): ');
    } else {

      stdout.writeln('Invalid input. Please enter an integer.');
    }
  }, onDone: () => sink.emit(-1));


  stdout.write('Press Ctrl+C or enter -1 to stop the stream.\n');
}

